$S I \perp(A B C D)$ và $\frac{d(D ;(S A C))}{d(I ;(S A C))}=\frac{D G}{I G}=2 \Rightarrow d(D ;(S A C))=2 . d(I ;(S A C))$.
\begin{itemize}
\item Gọi $K$ là trung điểm của $A O, H$ là hình chiếu của $I$ lên $S K$ ta có $I K \perp A C ; I H \perp(S A C)$
\end{itemize}
$\Rightarrow d(D ;(S A C))=2 . d(I ;(S A C))=2 . I H$
\begin{itemize}
